/*
 * This CSS script applies a semi-transparent, blurry overlay to a website's background.
 * It is best used with a browser extension like Stylish.
 */

/* Target the entire body of the webpage. */
body {
    /* Set the background attachment to 'fixed' to prevent the background from scrolling. */
    background-attachment: fixed;
}

/*
 * Create a pseudo-element before the body content. This allows the blur to sit behind
 * the main content without making the text and images blurry.
 */
body::before {
    /* Set the content property to an empty string. */
    content: "";
    
    /* Position the element to cover the entire viewport. */
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    
    /* Add a semi-transparent background color as a fallback for browsers that don't support backdrop-filter. */
    background: rgba(0, 0, 0, 0.5);

    /* Apply the magic! The backdrop-filter property blurs the elements behind it. */
    backdrop-filter: blur(10px);
    
    /* Add a transition for a smooth effect when the blur is applied or removed. */
    transition: backdrop-filter 0.3s ease-in-out;

    /* Ensure the overlay is behind the main content. */
    z-index: -1;
}

/* You can adjust the blur amount here! */
/* For example, to make the blur stronger: */
